/**
 * 診断情報をコピー — plain-text rendering of {@link DiagnosticsInfo}
 * (GUI_UX_SPEC §19). Japanese labels come from the copy deck values in
 * strings/ja.ts so the pasted report uses the same terms as the UI.
 * Values only — never stack traces or engine stderr.
 */

import { ja } from "../strings/ja";
import type { DiagnosticsInfo, ToolInfo, WorkerStatus } from "./types";

function toolLine(info: ToolInfo): string {
  const s = ja.dependencies;
  const status =
    info.status === "found"
      ? s.statusFound
      : info.status === "missing"
        ? s.statusMissing
        : info.status === "checking"
          ? s.statusChecking
          : ja.diagnostics.unknown;
  const extras = [info.version, info.path].filter(Boolean).join(" — ");
  return extras ? `${status}（${extras}）` : status;
}

function workerLine(status: WorkerStatus): string {
  const d = ja.diagnostics.workerStates;
  return status === "running"
    ? d.running
    : status === "stopped"
      ? d.stopped
      : status === "unavailable"
        ? d.unavailable
        : ja.diagnostics.unknown;
}

function value(v: string | number | null | undefined): string {
  return v == null || v === "" ? ja.diagnostics.notConnected : String(v);
}

/** One "ラベル: 値" per line — paste-ready for issue reports. */
export function formatDiagnosticsText(info: DiagnosticsInfo): string {
  const f = ja.diagnostics.fields;
  const lines: [string, string][] = [
    [f.appVersion, value(info.appVersion)],
    [
      f.engineVersion,
      info.engine ? `${info.engine.name} ${info.engine.version}` : value(null),
    ],
    [f.protocolVersion, value(info.protocolVersion)],
    [f.backend, value(info.backend)],
    [f.ffmpeg, toolLine(info.tools.ffmpeg)],
    [f.musescore, toolLine(info.tools.museScore)],
    [f.verovio, toolLine(info.tools.verovio)],
    [f.wavesurfer, toolLine(info.tools.wavesurfer)],
    [f.cachePath, value(info.paths.cache)],
    [f.logPath, value(info.paths.logs)],
    [f.workerStatus, workerLine(info.workerStatus)],
  ];
  return lines.map(([k, v]) => `${k}: ${v}`).join("\n");
}

/**
 * MockDiagnosticsPort — populated diagnostics data so the §19 surface is
 * fully exercisable in `vite dev` / vitest without an engine.
 *
 * Fields the real bridge cannot know yet (Verovio / wavesurfer versions)
 * report "unknown" honestly rather than fabricated numbers.
 *
 * Dev override: localStorage["hornscribe.dev.museScore"] === "missing"
 * makes MuseScore report missing (same flag the export mock honors, so the
 * tools section, the diagnostics sheet and the export dialog agree).
 */

import { getShellInfo } from "../tauri/bridge";
import {
  withPathOverride,
  type DiagnosticsInfo,
  type ToolInfo,
  type ToolPathOverrides,
} from "./types";
import { clipboardWrite, type DiagnosticsPort } from "./port";

const DEV_MUSESCORE_KEY = "hornscribe.dev.museScore";

export interface MockDiagnosticsPortOptions {
  museScore?: ToolInfo;
  ffmpeg?: ToolInfo;
  latencyMs?: number;
}

export class MockDiagnosticsPort implements DiagnosticsPort {
  private readonly options: MockDiagnosticsPortOptions;

  constructor(options: MockDiagnosticsPortOptions = {}) {
    this.options = options;
  }

  static withDevOverrides(): MockDiagnosticsPort {
    let museScore: ToolInfo | undefined;
    try {
      if (window.localStorage.getItem(DEV_MUSESCORE_KEY) === "missing") {
        museScore = { status: "missing" };
      }
    } catch {
      /* defaults are fine */
    }
    return new MockDiagnosticsPort({ museScore });
  }

  private delay(): Promise<void> {
    return new Promise((r) => setTimeout(r, this.options.latencyMs ?? 200));
  }

  async collect(overrides?: ToolPathOverrides): Promise<DiagnosticsInfo> {
    await this.delay();
    const shell = await getShellInfo().catch(() => null);
    const museScore =
      this.options.museScore ??
      ({
        status: "found",
        path: "C:\\Program Files\\MuseScore 4\\bin\\MuseScore4.exe",
        version: "4.x",
      } satisfies ToolInfo);
    const ffmpeg =
      this.options.ffmpeg ??
      ({
        status: "found",
        path: "C:\\tools\\ffmpeg\\bin\\ffmpeg.exe",
        version: "7.x",
      } satisfies ToolInfo);
    return {
      appVersion: shell?.version ?? "0.1.0 (dev)",
      engine: {
        name: "hornscribe-engine (mock)",
        version: "0.1.0",
        python: "3.12.x",
        platform: "win32",
      },
      protocolVersion: 1,
      backend: "basic-pitch (mock)",
      tools: {
        ffmpeg: withPathOverride(ffmpeg, overrides?.ffmpegPath),
        museScore: withPathOverride(museScore, overrides?.museScorePath),
        // Frontend libs are not integrated yet — honest "unknown".
        verovio: { status: "unknown" },
        wavesurfer: { status: "unknown" },
      },
      paths: {
        cache: "C:\\Users\\user\\AppData\\Local\\HornScribe\\cache",
        logs: "C:\\Users\\user\\AppData\\Local\\HornScribe\\logs",
      },
      workerStatus: "running",
    };
  }

  async copyText(text: string): Promise<boolean> {
    return clipboardWrite(text);
  }

  async openLogFolder(): Promise<boolean> {
    // Browsers cannot reveal OS folders — honest false; the sheet
    // announces the failure instead of pretending something opened.
    return false;
  }

  async restartEngine(): Promise<boolean> {
    await this.delay();
    return true; // the in-process mock "engine" always comes back
  }
}

/**
 * DiagnosticsPort contract tests (UI-060) — collect() is contractually
 * non-rejecting so the sheet can always render an honest picture; the
 * mock reports real-looking data labelled "(mock)" and honours the same
 * tool-path overrides as the export port.
 */

import { describe, expect, it } from "vitest";
import { MockDiagnosticsPort } from "./mockPort";
import { withPathOverride } from "./types";

describe("MockDiagnosticsPort.collect", () => {
  it("populates the full §19 surface", async () => {
    const info = await new MockDiagnosticsPort({ latencyMs: 0 }).collect();
    expect(info.appVersion).toBeTruthy();
    expect(info.engine?.name).toContain("mock");
    expect(info.protocolVersion).toBe(1);
    expect(info.tools.ffmpeg.status).toBe("found");
    expect(info.tools.museScore.status).toBe("found");
    // Frontend libs are not integrated — reported honestly, not invented.
    expect(info.tools.verovio.status).toBe("unknown");
    expect(info.paths.cache).toBeTruthy();
    expect(info.paths.logs).toBeTruthy();
    expect(info.workerStatus).toBe("running");
  });

  it("honours 設定 → ツール path overrides", async () => {
    const info = await new MockDiagnosticsPort({
      latencyMs: 0,
      museScore: { status: "missing" },
    }).collect({ museScorePath: "D:\\ms\\MuseScore4.exe" });
    expect(info.tools.museScore).toMatchObject({
      status: "found",
      path: "D:\\ms\\MuseScore4.exe",
    });
  });

  it("actions never throw: openLogFolder is honest false in a browser", async () => {
    const port = new MockDiagnosticsPort({ latencyMs: 0 });
    await expect(port.openLogFolder()).resolves.toBe(false);
    await expect(port.restartEngine()).resolves.toBe(true);
  });
