describe("withPathOverride", () => {
  it("empty/blank overrides leave the probe result alone", () => {
    const probed = { status: "missing" as const };
    expect(withPathOverride(probed, undefined)).toBe(probed);
    expect(withPathOverride(probed, "")).toBe(probed);
    expect(withPathOverride(probed, "   ")).toBe(probed);
  });

  it("a non-empty override wins and flips status to found", () => {
    expect(
      withPathOverride({ status: "missing" }, "  C:\\ms.exe  "),
    ).toEqual({ status: "found", path: "C:\\ms.exe" });
  });
});

/**
 * DiagnosticsPort — data seam for the 診断情報 surface (UI-060;
 * GUI_UX_SPEC §19: versions / tool status / cache+log paths / actions).
 *
 * Same gate pattern as `src/sidecar/port.ts` (UI-040) and
 * `src/export/port.ts`: the shell renders whatever the port can honestly
 * report — `collect()` resolves with per-field `null`/`unknown` instead of
 * rejecting, so diagnostics stays usable even with no engine.
 *
 * Gate:
 * - plain browser → {@link MockDiagnosticsPort}: an in-process fake that
 *   populates every field so the full surface is reviewable in `vite dev`;
 * - Tauri webview → {@link ShellDiagnosticsPort}: reports shell-side truth
 *   (app version via `shell_info`, no engine/tool probe — there is no
 *   spawn/fs bridge yet), and the actions report honest failure rather
 *   than pretending.
 */

import { getShellInfo, isTauriRuntime } from "../tauri/bridge";
import { MockDiagnosticsPort } from "./mockPort";
import type { DiagnosticsInfo, ToolPathOverrides } from "./types";

export interface DiagnosticsPort {
  /**
   * Gather the §19 surface. `overrides` carries the user-specified tool
   * paths from 設定 → ツール; non-empty paths override probing.
   * Never rejects: unavailable data is null/"unknown", so the sheet can
   * always render an honest picture.
   */
  collect(overrides?: ToolPathOverrides): Promise<DiagnosticsInfo>;
  /**
   * Copy already-formatted diagnostics text to the OS clipboard.
   * Resolves false when no clipboard path exists — the caller announces
   * the failure (clipboard may be absent/denied in some webviews).
   */
  copyText(text: string): Promise<boolean>;
  /** ログフォルダを開く — false when the bridge cannot reveal folders. */
  openLogFolder(): Promise<boolean>;
  /** エンジンを再起動 — false while no supervisor exists to restart. */
  restartEngine(): Promise<boolean>;
}

/**
 * Shell-only port: truthful about the app itself, honest `unknown`/`false`
 * for everything that needs the missing engine/fs bridge.
 */
export class ShellDiagnosticsPort implements DiagnosticsPort {
  async collect(): Promise<DiagnosticsInfo> {
    const shell = await getShellInfo();
    return {
      appVersion: shell?.version ?? null,
      engine: null,
      protocolVersion: null,
      backend: null,
      tools: {
        ffmpeg: { status: "unknown" },
        museScore: { status: "unknown" },
        verovio: { status: "unknown" },
        wavesurfer: { status: "unknown" },
      },
      paths: { cache: null, logs: null },
      workerStatus: "unavailable",
    };
  }
  async copyText(text: string): Promise<boolean> {
    return clipboardWrite(text);
  }
  async openLogFolder(): Promise<boolean> {
    return false;
  }
  async restartEngine(): Promise<boolean> {
    return false;
  }
}

/** Clipboard write shared by both ports (browser + webview). */
export async function clipboardWrite(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}

export function createDefaultDiagnosticsPort(): DiagnosticsPort {
  if (isTauriRuntime()) return new ShellDiagnosticsPort();
  return MockDiagnosticsPort.withDevOverrides();
}

/**
 * Shared capability / diagnostics types (UI-060).
 *
 * These mirror the sidecar handshake surface (`engine.handshake` →
 * `{protocolVersion, engineInfo, capabilities}` in protocol/PROTOCOL.md) so
 * a real engine can feed the same structures later — the TS side only needs
 * the contract surface today (issue: "export/backend capability reporting").
 * `src/sidecar/` (UI-040) owns the wire client; this file owns the
 * user-facing projection used by the export dialog, the settings tools
 * section and the diagnostics sheet.
 */

/** Engine identity from `engine.handshake` response `engineInfo`. */
export interface EngineInfo {
  readonly name: string;
  readonly version: string;
  readonly python?: string;
  readonly platform?: string;
  readonly pid?: number;
}

/** Detection state of an external tool (FFmpeg / MuseScore). */
export type ToolStatus = "found" | "missing" | "checking" | "unknown";

export interface ToolInfo {
  readonly status: ToolStatus;
  /** Resolved executable path when known (auto-detected or user-set). */
  readonly path?: string;
  readonly version?: string;
}

/**
 * Worker liveness as the shell sees it (never raw exit codes — the
 * supervisor vocabulary of ADR-0002: running / stopped / unavailable).
 */
export type WorkerStatus = "running" | "stopped" | "unavailable" | "unknown";

/** Everything the 診断情報 surface renders (GUI_UX_SPEC §19). */
export interface DiagnosticsInfo {
  /** App/shell version (`shell_info`); null when it cannot be read. */
  readonly appVersion: string | null;
  /** Engine handshake identity; null when the engine is not connected. */
  readonly engine: EngineInfo | null;
  readonly protocolVersion: number | null;
  /** Transcription backend id (e.g. "basic-pitch"); null when unknown. */
  readonly backend: string | null;
  /** External/bundled component status rows. */
  readonly tools: {
    readonly ffmpeg: ToolInfo;
    readonly museScore: ToolInfo;
    readonly verovio: ToolInfo;
    readonly wavesurfer: ToolInfo;
  };
  readonly paths: {
    readonly cache: string | null;
    readonly logs: string | null;
  };
  readonly workerStatus: WorkerStatus;
}

/** User-overridable tool paths (設定 → ツール). Empty string = auto-detect. */
export interface ToolPathOverrides {
  readonly museScorePath?: string;
  readonly ffmpegPath?: string;
}

/**
 * Merges a probed {@link ToolInfo} with a user-specified path: a non-empty
 * override wins (the user told us where the tool lives — the real probe
 * verifies it; until then the UI reports the override as the location).
 */
export function withPathOverride(
  probed: ToolInfo,
  overridePath: string | undefined,
): ToolInfo {
  const path = overridePath?.trim();
  if (!path) return probed;
  return { ...probed, status: "found", path };
}

