  permission: ja.errors.exportPermissionDenied.title,
  unavailable: ja.errors.engineUnavailable.title,
  musescore: ja.errors.musescoreMissing.title,
  failed: ja.errors.exportFailed.title,
};

const ERROR_BODY: Record<ErrorKind, string> = {
  permission: ja.errors.exportPermissionDenied.body,
  unavailable: ja.errors.engineUnavailable.body,
  musescore: ja.errors.musescoreMissing.body,
  failed: ja.errors.exportFailed.body,
};

/**
 * 書き出し dialog (GUI_UX_SPEC §17, §20; issue UI-060).
 *
 * Formats (all checked by default):
 *   楽譜: コンサートピッチ / F管ホルン MusicXML
 *   PDF:  コンサートピッチ / F管ホルン PDF  — disabled when MuseScore is
 *         missing, with the spec'd note + 場所を指定 recovery; MusicXML and
 *         MIDI stay available (acceptance: "missing MuseScore does not
 *         block other formats").
 *   MIDI: 再生用MIDI（実音） — sounding pitch only (ENG-001).
 *
 * Phases: loading → form → running → done | error. Errors keep the §20
 * shape (何が失敗したか → 影響 → 次にできること) and never render engine
 * output — only stable ExportError codes map to Japanese recovery copy.
 */
export function ExportDialog({
  open,
  onOpenChange,
  port,
  defaultDestination,
  toolOverrides,
  onOpenSettings,
  onOpenDiagnostics,
  onAnnounce,
}: {
  open: boolean;
  onOpenChange(open: boolean): void;
  port: ExportPort;
  /** 設定 → 書き出し → 既定の保存先 ("" = ask the port). */
  defaultDestination: string;
  /** 設定 → ツール user paths — non-empty paths override probing. */
  toolOverrides?: ToolPathOverrides;
  /** Recovery: opens 設定 focused on the 書き出し category. */
  onOpenSettings(category: "export"): void;
  onOpenDiagnostics(): void;
  onAnnounce(message: string): void;
}) {
  const [phase, setPhase] = useState<Phase>("loading");
  const [caps, setCaps] = useState<ExportCapabilities | null>(null);
  const [destination, setDestination] = useState("");
  const [selected, setSelected] = useState<Record<ExportFormatId, boolean>>({
    concertMusicxml: true,
    hornMusicxml: true,
    concertPdf: true,
    hornPdf: true,
    playbackMidi: true,
  });
  const [result, setResult] = useState<ExportResult | null>(null);
  const [errorKind, setErrorKind] = useState<ErrorKind>("failed");
  // Stale-response guard: a probe/export finishing after close or a newer
  // attempt must not overwrite the current phase.
  const generation = useRef(0);

  const e = ja.exportSheet;
  const errs = ja.errors;

  // Probe capabilities + destination when the dialog opens.
  useEffect(() => {
    if (!open) return;
    const gen = ++generation.current;
    setPhase("loading");
    setCaps(null);
    setResult(null);
    setSelected({
      concertMusicxml: true,
      hornMusicxml: true,
      concertPdf: true,
      hornPdf: true,
      playbackMidi: true,
    });
    let cancelled = false;
    void (async () => {
      try {
        const [capabilities, fallbackDir] = await Promise.all([
          port.capabilities(toolOverrides),
          defaultDestination
            ? Promise.resolve(defaultDestination)
            : port.defaultDestination(),
        ]);
        if (cancelled || generation.current !== gen) return;
        setCaps(capabilities);
        setDestination(defaultDestination || fallbackDir);
        setPhase("form");
      } catch (err) {
        if (cancelled || generation.current !== gen) return;
        setErrorKind(
          exportErrorCode(err) === "ENGINE_UNAVAILABLE"
            ? "unavailable"
            : "failed",
        );
        setPhase("error");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, port, defaultDestination, toolOverrides]);

  const close = useCallback(() => {
    generation.current += 1;
    onOpenChange(false);
  }, [onOpenChange]);

  const blocked = caps ? pdfBlocked(caps) : false;
  const anyChecked = Object.values(selected).some(Boolean);
  const running = phase === "running";

  const submit = useCallback(async () => {
    const gen = ++generation.current;
    setPhase("running");
    const formats = (
      Object.keys(selected) as ExportFormatId[]
    ).filter((f) => selected[f] && !(blocked && EXPORT_FORMAT_GROUPS[f] === "pdf"));
    try {
      const res = await port.export({ formats, destination });
      if (generation.current !== gen) return;
      setResult(res);
      setPhase("done");
      onAnnounce(ja.notifications.exportDone);
    } catch (err) {
      if (generation.current !== gen) return;
      const code = exportErrorCode(err);
      setErrorKind(
        code === "PERMISSION_DENIED"
          ? "permission"
          : code === "ENGINE_UNAVAILABLE"
            ? "unavailable"
            : code === "MUSESCORE_UNAVAILABLE"
              ? "musescore"
              : "failed",
      );
      setPhase("error");
    }
  }, [selected, blocked, port, destination, onAnnounce]);

  const pickDestination = useCallback(async () => {
    try {
      const dir = await port.chooseDestination(destination);
      if (dir) setDestination(dir);
    } catch {
      /* unsupported picker — the path row stays editable nowhere else,
         so surface the honest failure instead of dying silently */
      onAnnounce(ja.exportSheet.destinationPickFailed);
    }
  }, [port, destination, onAnnounce]);

  const reveal = useCallback(async () => {
    const dir = result?.destination ?? destination;
    const ok = await port.revealInExplorer(dir).catch(() => false);
    if (!ok) onAnnounce(ja.exportSheet.revealFailed);
  }, [port, result, destination, onAnnounce]);

  const goToMuseScoreSettings = useCallback(() => {
    close();
    onOpenSettings("export");
  }, [close, onOpenSettings]);

  const toggle =
    (key: ExportFormatId) =>
    (_: unknown, d: { checked: boolean | "mixed" }) =>
      setSelected((s) => ({ ...s, [key]: d.checked === true }));

  const title =
    phase === "done"
      ? e.completeTitle
      : phase === "error"
        ? ERROR_TITLE[errorKind]
        : e.title;

  const formatRow = (id: ExportFormatId) => {
    const disabled = running || (blocked && EXPORT_FORMAT_GROUPS[id] === "pdf");
    const checkbox = (
      <Checkbox
        checked={selected[id]}
        onChange={toggle(id)}
        label={e.options[id]}
        disabled={disabled}
      />
    );
    // Disabled checkboxes can't announce *why* — the spec'd tooltip does.
    return blocked && EXPORT_FORMAT_GROUPS[id] === "pdf" ? (
      <Tooltip
        key={id}
        content={e.pdfDisabledTooltip}
        relationship="label"
      >
        <span className="hs-export__option">{checkbox}</span>
      </Tooltip>
    ) : (
      <span key={id} className="hs-export__option">
        {checkbox}
      </span>
    );
  };

  return (
    <HsDialog
      open={open}
      onOpenChange={(o) => (o ? onOpenChange(true) : close())}
      title={title}
      actions={
        phase === "form" || running ? (
          <>
            <HsButton onClick={close}>{ja.common.cancel}</HsButton>
            <HsButton
              variant="primary"
              disabled={!anyChecked || running || !destination}
              loading={running}
              onClick={() => void submit()}
            >
              {running ? e.running : e.submit}
            </HsButton>
          </>
        ) : phase === "done" ? (
          <>
            <HsButton onClick={() => void reveal()}>
              {e.revealInExplorer}
            </HsButton>
            <HsButton variant="primary" onClick={close}>
              {ja.common.close}
            </HsButton>
          </>
        ) : phase === "error" ? (
          <>
            {errorKind === "permission" || errorKind === "failed" ? (
              <HsButton onClick={() => setPhase("form")}>
                {errs.exportPermissionDenied.actions.chooseDestination}
              </HsButton>
            ) : null}
            {errorKind === "failed" ? (
              <HsButton onClick={() => void submit()}>
                {errs.exportFailed.actions.retry}
              </HsButton>
            ) : null}
            {errorKind === "musescore" ? (
              <HsButton
                variant="primary"
                onClick={goToMuseScoreSettings}
              >
                {errs.musescoreMissing.actions.specifyMusescore}
              </HsButton>
            ) : null}
            {errorKind === "unavailable" ? (
              <HsButton
                variant="primary"
                onClick={() => {
                  close();
                  onOpenDiagnostics();
                }}
              >
                {errs.engineUnavailable.actions.diagnostics}
              </HsButton>
            ) : null}
            <HsButton onClick={close}>{ja.common.close}</HsButton>
          </>
        ) : undefined
      }
    >
      {phase === "loading" ? (
        <HsProgress label={e.loading} />
      ) : phase === "form" || running ? (
        <div className="hs-export">
          <h3 className="hs-export__section">{e.scoreSection}</h3>
          <div className="hs-export__group">
            {formatRow("concertMusicxml")}
            {formatRow("hornMusicxml")}
          </div>

          <h3 className="hs-export__section">{e.pdfSection}</h3>
          <div className="hs-export__group">
            {formatRow("concertPdf")}
            {formatRow("hornPdf")}
          </div>
          {blocked ? (
            <p className="hs-export__note" role="note">
              <Warning24Regular aria-hidden="true" />
              <span>{e.museScoreMissingNote}</span>
              <HsButton
                variant="subtle"
                size="small"
                onClick={goToMuseScoreSettings}
              >
                {e.specifyMuseScore}
              </HsButton>
            </p>
          ) : null}

          <h3 className="hs-export__section">{e.midiSection}</h3>
          <div className="hs-export__group">{formatRow("playbackMidi")}</div>

          <div className="hs-export__dest">
            <span className="hs-export__dest-label">{e.destination}</span>
            <span className="hs-export__dest-path" title={destination}>
              {destination}
            </span>
            <HsButton
              variant="secondary"
              size="small"
              disabled={running}
              onClick={() => void pickDestination()}
            >
              {ja.common.browse}
            </HsButton>
          </div>

          {running ? (
            <HsProgress label={e.running} className="hs-export__progress" />
          ) : null}
        </div>
      ) : phase === "done" ? (
        <div className="hs-export">
          <p className="hs-export__done">
            <CheckmarkCircle24Regular
              aria-hidden="true"
              className="hs-export__done-icon"
            />
            <span>
              {e.completeCount.replace(
                "{count}",
                String(result?.files.length ?? 0),
              )}
            </span>
          </p>
          <ul className="hs-export__files">
            {result?.files.map((f) => (
              <li key={f.format} title={f.path}>
                {f.name}
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <div className="hs-export">
          <p className="hs-export__error">
            <ErrorCircle24Regular
              aria-hidden="true"
              className="hs-export__error-icon"
            />
            <span>{ERROR_BODY[errorKind]}</span>
          </p>
        </div>
      )}
    </HsDialog>
  );
}

/**
 * ExportPort contract tests (UI-060) — run against MockExportPort, the
 * same in-process fake the dialog uses in `vite dev`. The port boundary
 * is what a real engine implements later, so the mock's behaviour is the
 * contract: ENG-001 artifact names, typed ExportError codes (never raw
 * engine output), and honest capability gating.
 */

import { describe, expect, it } from "vitest";
import { MockExportPort } from "./mockPort";
import {
  ExportError,
  EXPORT_FORMAT_IDS,
  exportErrorCode,
  pdfBlocked,
  type ExportPort,
} from "./types";

function port(options?: ConstructorParameters<typeof MockExportPort>[0]) {
  return new MockExportPort({ latencyMs: 0, ...options });
}

describe("MockExportPort.export", () => {
  it("writes only the requested formats with ENG-001 artifact names", async () => {
    const res = await port().export({
      formats: ["hornMusicxml", "playbackMidi"],
      destination: "C:\\out",
      basename: "take1",
    });
    expect(res.destination).toBe("C:\\out");
    expect(res.files.map((f) => f.name)).toEqual([
      "take1_horn_in_f.musicxml",
      "take1_playback.mid",
    ]);
    expect(res.files.map((f) => f.path)).toEqual([
      "C:\\out\\take1_horn_in_f.musicxml",
      "C:\\out\\take1_playback.mid",
    ]);
  });

  it("keeps the canonical format order regardless of selection order", async () => {
    const res = await port().export({
      formats: [...EXPORT_FORMAT_IDS].reverse(),
      destination: "D:\\",
    });
    expect(res.files.map((f) => f.format)).toEqual(EXPORT_FORMAT_IDS);
  });

  it("rejects with a typed ExportError when nothing is selected", async () => {
    await expect(
      port().export({ formats: [], destination: "C:\\out" }),
    ).rejects.toMatchObject({ name: "ExportError", code: "EXPORT_FAILED" });
  });

  it("maps every injected failure to its stable code", async () => {
    for (const code of [
      "PERMISSION_DENIED",
      "ENGINE_UNAVAILABLE",
      "MUSESCORE_UNAVAILABLE",
      "EXPORT_FAILED",
    ] as const) {
      const err = await port({ failure: code })
        .export({ formats: ["playbackMidi"], destination: "C:\\out" })
        .catch((e: unknown) => e);
      expect(err).toBeInstanceOf(ExportError);
      expect(exportErrorCode(err)).toBe(code);
    }
  });
});

describe("capabilities + pdf gate", () => {
  it("reports MuseScore found by default so PDF stays enabled", async () => {
    const caps = await port().capabilities();
    expect(caps.museScore.status).toBe("found");
    expect(pdfBlocked(caps)).toBe(false);
  });

  it("MuseScore missing blocks PDF only — other formats stay available", async () => {
    const caps = await port({ museScore: { status: "missing" } }).capabilities();
    expect(pdfBlocked(caps)).toBe(true);
    // The dialog's own filtering keeps score/midi formats enabled; the
    // gate never touches them.
    expect(caps.ffmpeg.status).toBe("found");
  });

  it("user-specified tool paths override probing (設定 → ツール)", async () => {
    const caps = await port({ museScore: { status: "missing" } }).capabilities({
      museScorePath: "D:\\MuseScore\\MuseScore4.exe",
    });
    expect(caps.museScore).toMatchObject({
      status: "found",
      path: "D:\\MuseScore\\MuseScore4.exe",
    });
    expect(pdfBlocked(caps)).toBe(false);
  });
});

describe("destination + reveal", () => {
  it("chooseDestination resolves a directory; reveal is honest false", async () => {
    const p: ExportPort = port({ defaultDestination: "C:\\Users\\me\\Documents" });
    await expect(p.chooseDestination()).resolves.toBe(
      "C:\\Users\\me\\Documents",
    );
    await expect(p.chooseDestination("E:\\picked")).resolves.toBe("E:\\picked");
    await expect(p.revealInExplorer("C:\\out")).resolves.toBe(false);
  });
});

describe("exportErrorCode", () => {
  it("collapses unknown throws to EXPORT_FAILED", () => {
    expect(exportErrorCode(new Error("boom"))).toBe("EXPORT_FAILED");
    expect(exportErrorCode("nope")).toBe("EXPORT_FAILED");
    expect(
      exportErrorCode(new ExportError("PERMISSION_DENIED", "x")),
    ).toBe("PERMISSION_DENIED");
  });
});

/**
 * MockExportPort — in-process emulation of the export backend so the §17
 * flow (formats, MuseScore gating, destination, progress, done/error
 * recovery) is exercisable in `vite dev` and vitest without a real engine.
 *
 * The fake reports an engine identity honestly labelled "(mock)" — the
 * diagnostics surface never pretends a real engine answered.
 *
 * Dev overrides (browser only, read once at construction):
 *   localStorage["hornscribe.dev.museScore"] === "missing"  → MuseScore
 *     reports missing so the PDF-disabled recovery path is reviewable;
 *   localStorage["hornscribe.dev.exportFailure"] in
 *     {"permission","engine","musescore","failed"}          → export()
 *     always rejects with the matching ExportError code so the error
 *     phases are reachable from the UI.
 */

import {
  withPathOverride,
  type EngineInfo,
  type ToolInfo,
  type ToolPathOverrides,
} from "../diagnostics/types";
import {
  ExportError,
  EXPORT_FORMAT_IDS,
  type ExportCapabilities,
  type ExportErrorCode,
  type ExportFormatId,
  type ExportPort,
  type ExportRequest,
  type ExportResult,
} from "./types";
import type { ExportedFile } from "./types";

/** ENG-001 filename policy: `<basename>_<artifact>`. */
const ARTIFACT_NAMES: Record<ExportFormatId, string> = {
  concertMusicxml: "concert.musicxml",
  hornMusicxml: "horn_in_f.musicxml",
  concertPdf: "concert.pdf",
  hornPdf: "horn_in_f.pdf",
  playbackMidi: "playback.mid",
};

const MOCK_ENGINE: EngineInfo = {
  name: "hornscribe-engine (mock)",
  version: "0.1.0",
  python: "3.12.x",
  platform: "win32",
};

const DEV_MUSESCORE_KEY = "hornscribe.dev.museScore";
const DEV_FAILURE_KEY = "hornscribe.dev.exportFailure";

const DEV_FAILURE_CODES: Record<string, ExportErrorCode> = {
  permission: "PERMISSION_DENIED",
  engine: "ENGINE_UNAVAILABLE",
  musescore: "MUSESCORE_UNAVAILABLE",
  failed: "EXPORT_FAILED",
};

export interface MockExportPortOptions {
  museScore?: ToolInfo;
  ffmpeg?: ToolInfo;
  /** Simulated latency for capabilities()/export(). */
  latencyMs?: number;
  /** Deterministic failure for export() — recovery-path tests. */
  failure?: ExportErrorCode;
  defaultDestination?: string;
}

export class MockExportPort implements ExportPort {
  private readonly options: Required<
    Pick<MockExportPortOptions, "latencyMs" | "defaultDestination">
  > &
    MockExportPortOptions;

  constructor(options: MockExportPortOptions = {}) {
    this.options = { latencyMs: 450, defaultDestination: "", ...options };
  }

  /** Browser-dev factory: honours the localStorage dev flags above. */
  static withDevOverrides(): MockExportPort {
    let museScore: ToolInfo | undefined;
    let failure: ExportErrorCode | undefined;
    try {
      if (window.localStorage.getItem(DEV_MUSESCORE_KEY) === "missing") {
        museScore = { status: "missing" };
      }
      const f = window.localStorage.getItem(DEV_FAILURE_KEY);
      if (f && f in DEV_FAILURE_CODES) failure = DEV_FAILURE_CODES[f];
    } catch {
      /* localStorage may be unavailable — defaults are fine */
    }
    return new MockExportPort({ museScore, failure });
  }

  private delay(): Promise<void> {
    return new Promise((r) => setTimeout(r, this.options.latencyMs));
  }

  async capabilities(
    overrides?: ToolPathOverrides,
  ): Promise<ExportCapabilities> {
    await this.delay();
    const museScore =
      this.options.museScore ??
      ({
        status: "found",
        path: "C:\\Program Files\\MuseScore 4\\bin\\MuseScore4.exe",
        version: "4.x",
      } satisfies ToolInfo);
    const ffmpeg =
      this.options.ffmpeg ??
      ({
        status: "found",
        path: "C:\\tools\\ffmpeg\\bin\\ffmpeg.exe",
        version: "7.x",
      } satisfies ToolInfo);
    return {
      engineInfo: MOCK_ENGINE,
      protocolVersion: 1,
      backend: "basic-pitch (mock)",
      museScore: withPathOverride(museScore, overrides?.museScorePath),
      ffmpeg: withPathOverride(ffmpeg, overrides?.ffmpegPath),
    };
  }

  async chooseDestination(current?: string): Promise<string | null> {
    await this.delay();
    // A browser has no native picker — the mock "chooses" deterministically
    // so the destination row exercises the populated state.
    return current ?? (this.options.defaultDestination || this.fallbackDir());
  }

  async defaultDestination(): Promise<string> {
    return this.options.defaultDestination || this.fallbackDir();
  }

  private fallbackDir(): string {
    return "C:\\Users\\user\\Documents\\HornScribe";
  }

  async export(request: ExportRequest): Promise<ExportResult> {
    await this.delay();
    const failure = this.options.failure;
    if (failure) {
      throw new ExportError(failure, `mock export failure: ${failure}`);
    }
    if (request.formats.length === 0) {
      throw new ExportError("EXPORT_FAILED", "no formats selected");
    }
    const basename = request.basename?.trim() || "score";
    const dir = request.destination;
    const files: ExportedFile[] = EXPORT_FORMAT_IDS.filter((f) =>
      request.formats.includes(f),
    ).map((format) => {
      const artifact = ARTIFACT_NAMES[format];
      const name = `${basename}_${artifact}`;
      return { format, name, path: `${dir}\\${name}` };
    });
    return { destination: dir, files };
  }

  async revealInExplorer(): Promise<boolean> {
    // No OS bridge in a browser — honest false; the dialog announces it.
    return false;
  }
}

/**
 * ExportPort — the seam between the 書き出し dialog and a concrete export
 * backend (UI-060).
 *
 * Same gate pattern as `src/sidecar/port.ts` (UI-040): the port owns the
 * capability probe and the export job, never the dialog logic; a real
 * implementation will wrap the sidecar client once the engine spawn bridge
 * lands, feeding `engine.handshake` capabilities into
 * {@link ExportCapabilities} (methods/jobKinds → supported formats,
 * engineInfo → diagnostics parity).
 *
 * ## Packaged-app gate
 *
 * No real spawn path exists yet: `src-tauri/capabilities/default.json`
 * grants no process/shell plugin permissions and no Rust supervisor is
 * wired. So `createDefaultExportPort()` returns:
 *
 * - {@link MockExportPort} in a plain browser (`vite dev` / vitest) — an
 *   in-process fake that exercises the full §17 flow including
 *   MuseScore-missing and permission-error recovery;
 * - {@link UnsupportedExportPort} inside the Tauri webview — every call
 *   fails explicitly with ENGINE_UNAVAILABLE, which the dialog maps to the
 *   honest 採譜エンジンに接続できません surface (診断情報 / 閉じる recovery),
 *   never a silent mock in the product shell.
 */

import { isTauriRuntime } from "../tauri/bridge";
import { MockExportPort } from "./mockPort";
import {
  ExportError,
  type ExportCapabilities,
  type ExportPort,
  type ExportResult,
} from "./types";

// The port contract lives in types.ts with the rest of the export model.
export type { ExportPort } from "./types";

/**
 * Explicit-failure port for environments without an export bridge —
 * currently every real Tauri runtime (see the gate note above). Each method
 * rejects/returns honestly so the dialog degrades to a recoverable state.
 */
export class UnsupportedExportPort implements ExportPort {
  capabilities(): Promise<ExportCapabilities> {
    return Promise.reject(
      new ExportError(
        "ENGINE_UNAVAILABLE",
        "export backend is not wired into the Tauri shell yet " +
          "(requires the engine spawn bridge; see src/export/port.ts)",
      ),
    );
  }
  chooseDestination(): Promise<string | null> {
    return Promise.reject(
      new ExportError(
        "ENGINE_UNAVAILABLE",
        "destination picker requires a shell bridge",
      ),
    );
  }
  defaultDestination(): Promise<string> {
    return Promise.reject(
      new ExportError("ENGINE_UNAVAILABLE", "no export backend"),
    );
  }
  export(): Promise<ExportResult> {
    return Promise.reject(
      new ExportError("ENGINE_UNAVAILABLE", "no export backend"),
    );
  }
  revealInExplorer(): Promise<boolean> {
    return Promise.resolve(false);
  }
}

export function createDefaultExportPort(): ExportPort {
  if (isTauriRuntime()) return new UnsupportedExportPort();
  return MockExportPort.withDevOverrides();
}

/**
 * Export contract types (UI-060; GUI_UX_SPEC §17; ENG-001 semantics).
 *
 * The dialog talks to a typed {@link ExportPort} (port.ts) — the same
 * port/gate layering the sidecar client uses (`src/sidecar/port.ts` in
 * UI-040): a mock port makes the whole UX exercisable in a plain browser,
 * while a real engine reports the same capability surface through the
 * `engine.handshake` response once the spawn bridge lands.
 */

import type {
  EngineInfo,
  ToolInfo,
  ToolPathOverrides,
} from "../diagnostics/types";

/**
 * The five export choices of §17. ENG-001 semantics:
 * - `concertMusicxml` / `hornMusicxml` → `*_concert.musicxml` /
 *   `*_horn_in_f.musicxml`; the F管ホルン artifact carries written pitches
 *   plus the -P5 `<transpose>` element so readers recover sounding pitch;
 * - `playbackMidi` → `*_playback.mid`, always *sounding* (concert) pitch —
 *   SMF has no transposing-instrument semantics, so a written-pitch MIDI
 *   would be ambiguous about its own pitch space (再生用MIDIは実音);
 * - `concertPdf` / `hornPdf` → rendered through MuseScore, hence gated by
 *   the MuseScore tool capability.
 */
export type ExportFormatId =
  | "concertMusicxml"
  | "hornMusicxml"
  | "concertPdf"
  | "hornPdf"
  | "playbackMidi";

/** Checkbox grouping from the spec mock-up (楽譜 / PDF / MIDI). */
export type ExportFormatGroup = "score" | "pdf" | "midi";

export const EXPORT_FORMAT_GROUPS: Record<ExportFormatId, ExportFormatGroup> = {
  concertMusicxml: "score",
  hornMusicxml: "score",
  concertPdf: "pdf",
  hornPdf: "pdf",
  playbackMidi: "midi",
};

export const EXPORT_FORMAT_IDS: readonly ExportFormatId[] = [
  "concertMusicxml",
  "hornMusicxml",
  "concertPdf",
  "hornPdf",
  "playbackMidi",
];

/**
 * The capability surface the export dialog needs — a subset of the engine
 * handshake plus local tool detection (MuseScore drives PDF availability;
 * FFmpeg is reported for consistency with diagnostics).
 */
export interface ExportCapabilities {
  readonly engineInfo: EngineInfo | null;
  readonly protocolVersion: number | null;
  /** Transcription backend id when known (diagnostics parity). */
  readonly backend: string | null;
  readonly museScore: ToolInfo;
  readonly ffmpeg: ToolInfo;
}

/** PDF export requires MuseScore; everything else stays available (§17). */
export function pdfBlocked(capabilities: ExportCapabilities): boolean {
  return capabilities.museScore.status !== "found";
}

/** A single written artifact returned by a successful export. */
export interface ExportedFile {
  readonly format: ExportFormatId;
  /** Absolute path of the written file. */
  readonly path: string;
  /** File name only (for display). */
  readonly name: string;
}

export interface ExportRequest {
  /** Formats to write — at least one, all enabled by capabilities. */
  readonly formats: readonly ExportFormatId[];
  /** Destination directory (absolute path). */
  readonly destination: string;
  /** Document base name for `<basename>_<artifact>` naming (ENG-001). */
  readonly basename?: string;
}

export interface ExportResult {
  readonly destination: string;
  readonly files: readonly ExportedFile[];
}

/**
 * Stable error codes the UI maps onto Japanese recovery copy — raw engine
 * messages and stack traces never reach the dialog (§20, acceptance:
 * "technical stack trace is not shown in normal error UI").
 */
export type ExportErrorCode =
  /** Destination is not writable (permission / read-only). */
  | "PERMISSION_DENIED"
  /** No engine connected (sidecar not spawned / crashed). */
  | "ENGINE_UNAVAILABLE"
  /** PDF was requested without a usable MuseScore. */
  | "MUSESCORE_UNAVAILABLE"
  /** Anything else — generic failure with retry/choose-destination. */
  | "EXPORT_FAILED";

export class ExportError extends Error {
  readonly code: ExportErrorCode;
  constructor(code: ExportErrorCode, message: string) {
    super(message);
    this.name = "ExportError";
    this.code = code;
  }
}

/** Maps an unknown thrown value to a stable code for the dialog. */
export function exportErrorCode(err: unknown): ExportErrorCode {
  if (err instanceof ExportError) return err.code;
  return "EXPORT_FAILED";
}

/**
 * ExportPort — the seam between the 書き出し dialog and a concrete export
 * backend (see port.ts for the runtime gate). Declared here with the rest
 * of the contract so implementations never import the port module itself.
 */
export interface ExportPort {
  /**
   * Probe export-relevant capabilities: engine identity, protocol version,
   * backend and tool detection. `overrides` carries the user-specified tool
   * paths from 設定 → ツール/書き出し (non-empty paths win over probing).
   * Rejects with ExportError(ENGINE_UNAVAILABLE) when no engine/backend
   * can answer — the dialog shows the recovery surface, not a crash.
   */
  capabilities(overrides?: ToolPathOverrides): Promise<ExportCapabilities>;
  /**
   * Ask the user for a destination directory (native picker where a real
   * bridge exists). Resolves null when the picker was cancelled.
   */
  chooseDestination(current?: string): Promise<string | null>;
  /**
   * The directory preselected in the dialog: the 設定 → 書き出し default
   * when set, else the engine/OS documents location.
   */
  defaultDestination(): Promise<string>;
  /**
   * Run the export. Resolves with the written artifacts; rejects with a
   * typed {@link ExportError} whose code drives the §20 recovery surface —
   * raw engine output/stack traces stay behind the port.
   */
  export(request: ExportRequest): Promise<ExportResult>;
  /**
   * Reveal a directory in the OS file manager (エクスプローラーで表示).
   * Resolves false where the bridge cannot do that — the caller announces
   * the failure instead of pretending.
   */
  revealInExplorer(path: string): Promise<boolean>;
}

/**
 * @vitest-environment jsdom
 *
 * Keyboard dispatcher tests (issue UI-012): IME safety, text-entry and
 * control scoping, disabled-command swallowing, auto-repeat and multi-chord
 * sequences.
 */

import { describe, expect, it, vi } from "vitest";
import { CommandRegistry } from "../commands/registry";
import { createCommandDefinitions } from "../commands/definitions";
import type {
  Command,
  CommandContext,
  CommandSnapshot,
} from "../commands/types";
import { KeyboardDispatcher } from "./dispatcher";
import type { KeyEventLike } from "./keys";

const EMPTY: CommandSnapshot = {
  hasAudio: false,
  hasScore: false,
  isTranscribing: false,
  isPlaying: false,
  loopEnabled: false,
  pitch: "concert",
  canUndo: false,
  canRedo: false,
  hasSelection: false,
  reviewOpen: false,
  reviewCount: 0,
  view: "workspace",
};

const WITH_AUDIO: CommandSnapshot = { ...EMPTY, hasAudio: true };

function mockContext() {
  const calls: string[] = [];
  const spy = (name: string) => vi.fn(() => calls.push(name));
  const ctx: CommandContext = {
    openAudio: spy("openAudio"),
    transcribe: spy("transcribe"),
    togglePlayPause: spy("togglePlayPause"),
    stop: spy("stop"),
    jumpBack: spy("jumpBack"),
    jumpForward: spy("jumpForward"),
    seekToStart: spy("seekToStart"),
    seekToEnd: spy("seekToEnd"),
    toggleLoop: spy("toggleLoop"),
    setPitchView: spy("setPitchView"),
    openReview: spy("openReview"),
    reviewNext: spy("reviewNext"),
    reviewPrevious: spy("reviewPrevious"),
    undo: spy("undo"),
    redo: spy("redo"),
    openExport: spy("openExport"),
    zoomScoreIn: spy("zoomScoreIn"),
    zoomScoreOut: spy("zoomScoreOut"),
    zoomScoreFit: spy("zoomScoreFit"),
    clearSelection: spy("clearSelection"),
    openSettings: spy("openSettings"),
    openDiagnostics: spy("openDiagnostics"),
    focusNextRegion: spy("focusNextRegion"),
    focusPreviousRegion: spy("focusPreviousRegion"),
    announce: spy("announce"),
  };
  return { ctx, calls };
}

function key(
  k: string,
  init: Partial<KeyEventLike> = {},
): KeyEventLike {
  return {
    key: k,
    ctrlKey: false,
    shiftKey: false,
    altKey: false,
    ...init,
  };
}

function setup(
  snapshot: CommandSnapshot,
  commands: readonly Command[] = createCommandDefinitions(),
) {
  const { ctx, calls } = mockContext();
  const dispatcher = new KeyboardDispatcher({
    registry: new CommandRegistry(commands),
    getSnapshot: () => snapshot,
    context: ctx,
  });
  return { dispatcher, calls };
}

describe("basic dispatch", () => {
  it("runs a bound command and asks for preventDefault", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const result = dispatcher.handleKeyDown(key(" "));
    expect(result).toMatchObject({
      kind: "ran",
      commandId: "transport.playPause",
      shouldPreventDefault: true,
    });
    expect(calls).toEqual(["togglePlayPause"]);
  });

  it("K is the second play/pause binding (§9)", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    expect(dispatcher.handleKeyDown(key("k")).commandId).toBe(
      "transport.playPause",
    );
    expect(calls).toEqual(["togglePlayPause"]);
  });

  it("letters match case-insensitively but modifiers stay strict", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    // CapsLock makes e.key "J" — still the same chord.
    expect(dispatcher.handleKeyDown(key("J")).commandId).toBe(
      "transport.jumpBack",
    );
    // But Shift+L is not bound — modifier mismatch means no dispatch.
    const shifted = dispatcher.handleKeyDown(key("L", { shiftKey: true }));
    expect(shifted.kind).toBe("unmatched");
    expect(calls).toEqual(["jumpBack"]);
  });

  it("unmatched keys pass through without preventDefault", () => {
    const { dispatcher } = setup(WITH_AUDIO);
    const result = dispatcher.handleKeyDown(key("q"));
    expect(result).toMatchObject({
      kind: "unmatched",
      shouldPreventDefault: false,
    });
  });
});

describe("disabled commands stay non-executable", () => {
  it("swallows a known-but-disabled shortcut (no run, preventDefault)", () => {
    const { dispatcher, calls } = setup(EMPTY); // no audio
    const result = dispatcher.handleKeyDown(key(" "));
    expect(result).toMatchObject({
      kind: "disabled",
      commandId: "transport.playPause",
      shouldPreventDefault: true,
    });
    expect(calls).toEqual([]);
  });

  it("Ctrl+Z does nothing when the undo stack is empty", () => {
    const { dispatcher, calls } = setup(EMPTY);
    expect(dispatcher.handleKeyDown(key("z", { ctrlKey: true })).kind).toBe(
      "disabled",
    );
    expect(calls).toEqual([]);
  });
});

describe("IME safety (UI_COPY_CONTRACT / MASTER_PLAN §8)", () => {
  it("ignores events during composition", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const result = dispatcher.handleKeyDown(
      key("k", { isComposing: true }),
    );
    expect(result.kind).toBe("suppressed");
    expect(result.shouldPreventDefault).toBe(false);
    expect(calls).toEqual([]);
  });

  it("ignores the keyCode 229 IME sentinel", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const result = dispatcher.handleKeyDown(
      key("Process", { keyCode: 229 }),
    );
    expect(result.kind).toBe("suppressed");
    expect(calls).toEqual([]);
  });
});

describe("focus scopes", () => {
  function el(html: string): HTMLElement {
    const host = document.createElement("div");
    host.innerHTML = html;
    const node = host.firstElementChild as HTMLElement;
    document.body.appendChild(node);
    return node;
  }

  it("suppresses J/K/L inside text input (spec §9)", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const input = el('<input type="text">');
    const result = dispatcher.handleKeyDown(key("k", { target: input }));
    expect(result.kind).toBe("suppressed");
    expect(calls).toEqual([]);
    input.remove();
  });

  it("suppresses Ctrl+Z inside text input — field-level undo wins", () => {
    const { dispatcher, calls } = setup({ ...EMPTY, canUndo: true });
    const textarea = el("<textarea></textarea>");
    const result = dispatcher.handleKeyDown(
      key("z", { ctrlKey: true, target: textarea }),
    );
    expect(result.kind).toBe("suppressed");
    expect(calls).toEqual([]);
    textarea.remove();
  });

  it("suppresses everything inside a modal surface by default", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const dialog = el('<div role="dialog"><button type="button">x</button></div>');
    const inside = dialog.querySelector("button")!;
    for (const k of ["k", " "]) {
      expect(
        dispatcher.handleKeyDown(key(k, { target: inside })).kind,
      ).toBe("suppressed");
    }
    // Even a Ctrl binding does not fire inside a modal.
    expect(
      dispatcher.handleKeyDown(
        key("o", { ctrlKey: true, target: inside }),
      ).kind,
    ).toBe("suppressed");
    expect(calls).toEqual([]);
    dialog.remove();
  });

  it("Space on a focused button belongs to the button, not transport", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const button = el('<button type="button">開く</button>');
    const result = dispatcher.handleKeyDown(key(" ", { target: button }));
    expect(result.kind).toBe("suppressed");
    expect(calls).toEqual([]);
    button.remove();
  });

  it("J on a focused button still dispatches — buttons don't consume J", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const button = el('<button type="button">開く</button>');
    const result = dispatcher.handleKeyDown(key("j", { target: button }));
    expect(result).toMatchObject({
      kind: "ran",
      commandId: "transport.jumpBack",
    });
    expect(calls).toEqual(["jumpBack"]);
    button.remove();
  });

  it("Space on a radio stays with the control (roving tabindex)", () => {
    const { dispatcher } = setup(WITH_AUDIO);
    const radio = el('<div role="radio" tabindex="0"></div>');
    // Space checks the radio instead of toggling playback.
    expect(
      dispatcher.handleKeyDown(key(" ", { target: radio })).kind,
    ).toBe("suppressed");
    radio.remove();
  });

  it("Ctrl bindings still work from inside a focused control", () => {
    const { dispatcher, calls } = setup(EMPTY);
    const button = el('<button type="button">開く</button>');
    const result = dispatcher.handleKeyDown(
      key("o", { ctrlKey: true, target: button }),
    );
    expect(result).toMatchObject({
      kind: "ran",
      commandId: "file.openAudio",
    });
    expect(calls).toEqual(["openAudio"]);
    button.remove();
  });

  it("allowInTextInput commands still fire inside text fields", () => {
    const { ctx, calls } = mockContext();
    const commands: Command[] = [
      {
        id: "test.inText",
        title: "テスト",
        section: "app",
        shortcuts: ["Ctrl+S"],
        allowInTextInput: true,
        run: () => calls.push("inText"),
      },
    ];
    const dispatcher = new KeyboardDispatcher({
      registry: new CommandRegistry(commands),
      getSnapshot: () => EMPTY,
      context: ctx,
    });
    const input = el('<input type="text">');
    expect(
      dispatcher.handleKeyDown(key("s", { ctrlKey: true, target: input }))
        .kind,
    ).toBe("ran");
    expect(calls).toEqual(["inText"]);
    input.remove();
  });
});

describe("shift-implicit symbol keys (§15 zoom bindings)", () => {
